<?php
require_once __DIR__.'/includes/functions.php'; $user=require_login(); require_permission($user,'radiology.manage'); $pageTitle='Radiologi'; $pdo=db();
$pdo->exec("CREATE TABLE IF NOT EXISTS radiology_attachments (id INT AUTO_INCREMENT PRIMARY KEY, radiology_order_id INT NOT NULL, description VARCHAR(200) NOT NULL, stored_name VARCHAR(120) NOT NULL, original_name VARCHAR(255) NOT NULL, mime_type VARCHAR(90) NOT NULL, uploaded_by INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(radiology_order_id) REFERENCES radiology_orders(id), FOREIGN KEY(uploaded_by) REFERENCES employees(id)) ENGINE=InnoDB");
if($_SERVER['REQUEST_METHOD']==='POST'){
 if($user['role_code']!=='radiologi'){http_response_code(403);exit('Hanya petugas radiologi yang dapat menginput hasil dan mengunggah arsip radiologi.');} check_csrf();
 $id=(int)($_POST['radiology_id']??0);$action=$_POST['action']??'result';
 try{
  $q=$pdo->prepare('SELECT id FROM radiology_orders WHERE id=?');$q->execute([$id]);if(!$q->fetchColumn())throw new RuntimeException('Order radiologi tidak ditemukan.');
  if($action==='upload'){
   $desc=trim($_POST['description']??'');$file=$_FILES['attachment']??null;if(!$desc||!$file||$file['error']!==UPLOAD_ERR_OK||$file['size']>20*1024*1024)throw new RuntimeException('Isi keterangan dan pilih file maksimal 20 MB.');
   $mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$allowed=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png'];if(!isset($allowed[$mime]))throw new RuntimeException('Arsip hanya menerima PDF, JPG, atau PNG.');
   $dir=__DIR__.'/private_uploads';if(!is_dir($dir))mkdir($dir,0700,true);$stored=bin2hex(random_bytes(20)).'.'.$allowed[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$stored))throw new RuntimeException('Gagal menyimpan arsip.');
   $pdo->prepare('INSERT INTO radiology_attachments(radiology_order_id,description,stored_name,original_name,mime_type,uploaded_by) VALUES(?,?,?,?,?,?)')->execute([$id,$desc,$stored,basename($file['name']),$mime,$user['employee_id']]);
   flash('success','Berkas hasil radiologi berhasil diarsipkan.');
  }else{
   $result=trim($_POST['result']??'');if(!$result)throw new RuntimeException('Isi hasil/ekspertise radiologi.');
   $pdo->prepare("UPDATE radiology_orders SET status='Selesai',result=?,verified_by=?,verified_at=NOW() WHERE id=?")->execute([$result,$user['employee_id'],$id]);
   $pdo->prepare("UPDATE orders o JOIN radiology_orders ro ON ro.order_id=o.id SET o.status='Completed' WHERE ro.id=?")->execute([$id]);flash('success','Hasil radiologi berhasil disimpan.');
  }
 }catch(Throwable $e){flash('error',$e->getMessage());} redirect('radiology.php?q='.urlencode(trim($_GET['q']??'')));
}
$search=trim($_GET['q']??'');$params=[];$where='1=1';if($search!==''){$where='(p.full_name LIKE ? OR p.medical_record_no LIKE ? OR r.registration_no LIKE ?)';$params=['%'.$search.'%','%'.$search.'%','%'.$search.'%'];}
$sql="SELECT ro.id,ro.exam_name,ro.clinical_indication,ro.status,ro.result,ro.verified_at,o.order_no,r.registration_no,p.id patient_id,p.full_name patient_name,p.medical_record_no,d.full_name doctor_name FROM radiology_orders ro JOIN orders o ON o.id=ro.order_id JOIN registrations r ON r.id=o.registration_id JOIN patients p ON p.id=r.patient_id JOIN employees d ON d.id=o.ordering_employee_id WHERE $where ORDER BY ro.id DESC";$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();
require __DIR__.'/includes/header.php'; ?>
<h1 class="page-title">Radiologi dan Arsip Hasil</h1><p class="page-subtitle">Petugas radiologi mengisi ekspertise dan mengunggah hasil pemeriksaan. Hasil dapat ditelusuri berdasarkan pasien atau nomor registrasi.</p>
<div class="card"><form method="get" class="grid grid-3"><div class="field"><label>Cari pasien / No. RM / No. Registrasi</label><input class="input" name="q" value="<?=e($search)?>" placeholder="Nama atau nomor pasien"></div><div class="field" style="align-self:end"><button class="btn btn-primary">Cari Hasil Radiologi</button></div></form></div>
<div class="card" style="margin-top:18px"><h2 class="section-title">Arsip Hasil Pemeriksaan per Pasien</h2><div class="table-wrap"><table><thead><tr><th>Pasien / Registrasi</th><th>Pemeriksaan</th><th>Dokter Peminta</th><th>Hasil / Ekspertise</th><th>Arsip Berkas</th></tr></thead><tbody>
<?php foreach($rows as $r):?><tr><td><b><?=e($r['patient_name'])?></b><small><?=e($r['medical_record_no'].' · '.$r['registration_no'])?></small></td><td><?=e($r['exam_name'])?><small><?=e($r['clinical_indication'])?></small><span class="badge <?= $r['status']==='Selesai'?'badge-green':'badge-yellow' ?>"><?=e(status_label($r['status']))?></span></td><td><?=e($r['doctor_name'])?></td><td><?php if($r['result']):?><?=nl2br(e($r['result']))?><?php else:?><span class="note">Belum tersedia</span><?php endif;?><?php if($user['role_code']==='radiologi' && $r['status']!=='Selesai'):?><form method="post" style="margin-top:8px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="radiology_id" value="<?=$r['id']?>"><input type="hidden" name="action" value="result"><textarea class="input" name="result" placeholder="Hasil / ekspertise" required></textarea><button class="btn btn-primary btn-sm" style="margin-top:6px">Simpan Hasil</button></form><?php endif;?></td><td><?php $a=$pdo->prepare('SELECT id,description,original_name FROM radiology_attachments WHERE radiology_order_id=? ORDER BY id DESC');$a->execute([$r['id']]);foreach($a as $file):?><a href="radiology_file.php?id=<?=$file['id']?>" target="_blank"><?=e($file['description'].' · '.$file['original_name'])?></a><br><?php endforeach;?><?php if($user['role_code']==='radiologi'):?><form method="post" enctype="multipart/form-data" style="margin-top:8px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="radiology_id" value="<?=$r['id']?>"><input type="hidden" name="action" value="upload"><input class="input" name="description" placeholder="Keterangan file" required><input class="input" type="file" name="attachment" accept=".pdf,.jpg,.jpeg,.png" required style="margin-top:6px"><button class="btn btn-secondary btn-sm" style="margin-top:6px">Arsipkan Hasil</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">Belum ada hasil/order radiologi yang sesuai pencarian.</td></tr><?php endif;?></tbody></table></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
